-- Annapurna Store Master & Operational Database Schema
-- Created for DMW Lab Exam Question 1

CREATE TABLE IF NOT EXISTS stores (
    store_id VARCHAR(10) PRIMARY KEY,
    store_name VARCHAR(100) NOT NULL,
    city VARCHAR(100) NOT NULL,
    state VARCHAR(100) NOT NULL
);

CREATE TABLE IF NOT EXISTS products (
    product_sk SERIAL PRIMARY KEY,
    product_code VARCHAR(20) NOT NULL,
    product_name VARCHAR(150) NOT NULL,
    category VARCHAR(100) NOT NULL,
    valid_from DATE NOT NULL,
    valid_to DATE NOT NULL
);

CREATE TABLE IF NOT EXISTS price_revisions (
    revision_id SERIAL PRIMARY KEY,
    product_sk INT REFERENCES products(product_sk),
    effective_from DATE NOT NULL,
    effective_to DATE NOT NULL,
    price NUMERIC(10,2) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_products_lookup ON products(product_code, valid_from, valid_to);
CREATE INDEX IF NOT EXISTS idx_price_effective ON price_revisions(product_sk, effective_from, effective_to);

